/* PageMenuClose: closes the pause menu. */
void close_pause_menu(void) {
    int i;
    int value;
    int handle;
    unsigned char *table;
    char *st = level_menu_system;

    if (*(int *)(st + 0x110) >= 10) {
        VU1_syncChain(1);
        VU1_initChain();
        if (*(int *)(st + 4) != 0) {
            {
                for (i = 0; i < 14; i++) {
                    MenuSystem *s = (MenuSystem *)level_menu_system;
                    MenuScreen *screen = s->current->screens[i];
                    if (screen != 0) {
                        if (screen->leave != 0) {
                            screen->leave(screen, 0);
                        }
                    }
                }
            }
            {
                MenuSystem *s = (MenuSystem *)level_menu_system;
                s->current = 0;
            }
        }
        {
            int i;
            int value = 0x26;
            for (i = 3; i >= 0; i--) {
                MenuSystem *s = (MenuSystem *)level_menu_system;
                struct Hero *h = (struct Hero *)g_hero;
                if (((int *)last_weapon_id)[3 - i] != s->equipped[3 - i]) {
                    h->pending_item[3 - i] = s->equipped[3 - i] != 0 ? s->equipped[3 - i] : value;
                }
            }
        }
        {
            MenuSystem *state = (MenuSystem *)level_menu_system;
            int value;
            table = texture_group_header;
            value = *(int *)(*(char **)(table + 0x18) + 0x74);
            *(int *)&g_gs_texture_allocation_start = state->saved_texture_start;
            Hud_SendResidentBank(0, value, 0);
        }
        apply_group_entry_adjustment(2);
        if (*(int *)(*(char **)(table + 0x18) + 0x80) != 0) {
            apply_group_entry_adjustment(3);
        }
        if (*(int *)(*(char **)(table + 0x18) + 0x84) != 0) {
            apply_group_entry_adjustment(4);
        }
        {
            int k;
            for (k = 0; k < 14; k++) {
                menu_preview_mobys[k] = delete_moby(menu_preview_mobys[k]);
            }
        }
        handle = show_health_hud();
        hud_keep_visible(handle, scale_ticks(0xB4));
        handle = queue_animation_update(2, 0x754E, initialize_bolt_counter_hud,
                                        update_bolt_counter_hud_animation_and_visibility, draw_bolt_counter_hud_panel,
                                        &gBolts, 9999999);
        hud_keep_visible(handle, scale_ticks(0xB4));
        {
            char *s = level_menu_system;
            *(int *)s = 0x14;
            *(int *)(s + 0x14) = 2;
            value = *(int *)(s + 0xCC);
            while (value < moby_class_headers[0]->seq_count) {
                moby_class_headers[0]->seqs[value] = 0;
                value++;
            }
        }
        {
            char *s = level_menu_system;
            moby_class_headers[0]->seq_count = *(unsigned char *)(s + 0xCC);
        }
        skip_frame = 1;
        {
            int *tbl = (int *)coll_hit_result;
            ((struct {
                int p[4];
                int f;
            } *)tbl)
                ->f &= 0x7FFFFFFF;
        }
        VU1_sendChain();
        VU1_syncChain(1);
    }
}
