/* loads the saved pause-menu state block into the game globals */
void restore_or_clear_level_state(void) {
    struct CheckpointState *p = (struct CheckpointState *)((char *)checkpoint_level_state);
    struct Hero *g;
    unsigned char *b;
    char *e;
    int k, s, i;
    if (*(int *)checkpoint_level_state == 0) {
        FastMemSet(current_level_state, 0, 0xC60);
        return;
    }
    copy_memory_by_alignment((int)current_level_state, p, 0xC60);
    qcopy(g_hero + 0x80, &p->hero_pos);
    qcopy(g_hero + 0x90, &p->hero_rot);
    g = (struct Hero *)((unsigned char *)g_hero);
    *(int *)(*(char **)&g->moby + 0x38) = p->unk_30;
    *(int *)(*(char **)&g->moby + 0x3C) = p->unk_34;
    *(int *)(*(char **)&g->moby + 0x80) = p->unk_38;
    b = (unsigned char *)voice_pool;
    *(int *)(b + 0x64) = p->unk_3C;
    b[0x68] = *(char *)&p->unk_40;
    b[0x69] = *(char *)&p->unk_41;
    b[0x6A] = *(char *)&p->unk_42;
    *(unsigned short *)(&help_stats_base + 0x100ED) = *(unsigned short *)&p->unk_C54;
    b[0x6B] |= 7;
    k = p->vehicle_mode;
    if (k == 0 || k == 3)
        goto done;
    s = 0;
    switch (k) {
        case 1:
            s = 0x57;
            break;
        case 2:
            s = 0x1A3;
            break;
        default:
            raise_kernel_trap();
    }
    for (i = 0; (e = (char *)moby_array_start + (i << 8)) < (char *)level_mobys_end; i++) {
        if (*(short *)(e + 0xA6) == s) {
            int *q = (int *)checkpoint_level_state;
            enter_hero_vehicle_mode(q[0x11], q[0x13], e);
            break;
        }
    }
done: {
    struct Hero *h = (struct Hero *)g_hero;
    moby_build_matrix(*(void **)&h->moby);
    euler_rotation_basis(*(char **)&h->moby + 0xC0, &h->motion.rot);
}
    init_camera_system();
    register_audio_stream_callback();
}
