/* Finds the 0x100-byte record whose short at +0xB2 equals id, or 0 if none. */
int find_moby_by_id(int a, int id) {
    unsigned char *p;
    for (p = moby_array_start; p != level_mobys_end; p += 0x100) {
        if (*(short *)(p + 0xB2) == id)
            return (int)p;
    }
    return 0;
}
